// ── Imágenes embebidas (base64) ──
const IMAGES = {
  logo:  'data:image/png;base64,',
  food1: 'data:image/png;base64,',
  food2: 'data:image/png;base64,',
  rest1: 'data:data:image/png;base64,',
};

// ── Inyección de imágenes ──
document.addEventListener('DOMContentLoaded', () => {
  document.querySelectorAll('[data-src]').forEach(el => {
    const key = el.getAttribute('data-src');
    if (IMAGES[key]) el.src = IMAGES[key];
  });

  initNav();
  initReveal();
  initHamburger();
});

// ── Nav scroll ──
function initNav() {
  const nav = document.getElementById('navbar');
  const onScroll = () => nav.classList.toggle('scrolled', window.scrollY > 60);
  window.addEventListener('scroll', onScroll, { passive: true });
  onScroll();
}

// ── Hamburger mobile ──
function initHamburger() {
  const btn = document.getElementById('hamburger');
  const menu = document.getElementById('navMobile');
  btn.addEventListener('click', () => {
    btn.classList.toggle('open');
    menu.classList.toggle('open');
  });
}
function closeMenu() {
  document.getElementById('hamburger').classList.remove('open');
  document.getElementById('navMobile').classList.remove('open');
}

// ── Scroll reveal ──
function initReveal() {
  const els = document.querySelectorAll('.reveal');
  const obs = new IntersectionObserver((entries) => {
    entries.forEach(e => {
      if (e.isIntersecting) {
        e.target.classList.add('visible');
        obs.unobserve(e.target);
      }
    });
  }, { threshold: 0.1 });
  els.forEach(el => obs.observe(el));
}

// ── Formulario ──
function handleSubmit() {
  const btn = document.getElementById('submitBtn');
  btn.textContent = '¡Reservación enviada! Te contactamos pronto ◆';
  btn.disabled = true;
}
